      else for (const fn of this.handlers.get(m.method) || []) fn(m.params);
    });
  }
  on(event, fn) { const h = this.handlers.get(event) || []; h.push(fn); this.handlers.set(event, h); }
  send(method, params = {}) {
    return new Promise((resolve, reject) => {
      const id = ++this.seq;
