  return [...controls.map(c => c[0]), 'oversize output',...dependencyControls.map(c=>c[0]),'snapshot service-worker entry','snapshot runtime asset'];
}

function readOutput(dir) {
  const files = new Map(); let bytes = 0;
  function visit(base) {
    for (const entry of fs.readdirSync(base, {withFileTypes: true})) {
      const full = path.join(base, entry.name);
      assert(!entry.isSymbolicLink(), `Unexpected built symlink: ${full}`);
      if (entry.isDirectory()) visit(full);
      else {const name = path.relative(dir, full).split(path.sep).join('/'); const data = fs.readFileSync(full); files.set(name, data); bytes += data.length;}
    }
  }
  visit(dir); return {files, bytes};
}

const {normalizeCowAimCacheScope}=require('./helpers/cow-aim-cache-scope.cjs');
const {normalizeCowSpaceScope}=require('./helpers/cow-space-scope.cjs'); // A40
