    const fieldNormalized=normalizeFieldScope(file,a39Bytes.toString('utf8'));
    const fieldBytes=fieldNormalized===a39Bytes.toString('utf8')?a39Bytes:Buffer.from(fieldNormalized);
    if (a39Bytes !== bytes && file !== 'sw.js') historical = a39Bytes;
    if (file === 'auth.js' || file === 'index.html') {
      const exact = approved[file];
      assert.equal(sha(fieldBytes), exact.afterSha256, `Unknown A38 current bytes: ${entry.path}`);
      let text = fieldBytes.toString('utf8');
      for (const h of exact.hunks) {
        assert.equal(text.split(h.after).length, 2, `A38 unique approved hunk: ${entry.path}`);
        text = text.replace(h.after, h.before);
      }
      historical = Buffer.from(text);
      assert.equal(sha(historical), exact.beforeSha256, `A38 exact reconstruction: ${entry.path}`);
    } else if (file === 'sw.js') {
      assert.equal(sha(fieldBytes), '82e259feda9c3fedc0b492d737c35eef08aa4d208195542b4b403d47038109ad', 'Unknown A38 current service worker');
      let text = fieldBytes.toString('utf8');
      for (const [after, before] of [['const CACHE = "sa3d-v75";', 'const CACHE = "sa3d-v74";'], ['"auth.js?v=21"', '"auth.js?v=20"']]) {
        assert.equal(text.split(after).length, 2, 'A38 unique service-worker version hunk');
        text = text.replace(after, before);
      }
      historical = Buffer.from(text);
      assert.equal(sha(historical), '490ca027327721412f0c67a315ac2db63ea98f2562d500214ac9c8cc667c98c0', 'A38 exact service-worker reconstruction');
    }
    assert.equal(blob(historical), entry.blob, `Source changed since tested checkpoint: ${entry.path}`);
    if (historical === bytes) unchanged.push(entry.path);
    else changes.push({path: entry.path, currentSha256: sha(bytes), originalBlob: entry.blob});
  }
  assert.equal(unchanged.length, 114, 'All other runtime assets stay unchanged'); // A45: sheep3d.js and chicken3d.js join the accounted changes
  assert.deepEqual(changes.map(c => c.path).sort(), ['farm3d/auth.js', 'farm3d/chicken3d.js', 'farm3d/cow3d.js', 'farm3d/index.html', 'farm3d/quadruped3d.js', 'farm3d/sheep3d.js', 'farm3d/sw.js']);
  return {unchangedRuntimeAssets: unchanged.length, approvedRuntimeChanges: changes};
}

function accountingControls(source, manifest) {
  historicalAccounting(source, manifest);
  const controls = [
    ['wrong auth', m => m.set('farm3d/auth.js', Buffer.concat([m.get('farm3d/auth.js'), Buffer.from('\n/* unrelated */')]))],
    ['unrelated game change', m => m.set('farm3d/game.js', Buffer.concat([m.get('farm3d/game.js'), Buffer.from('\n/* unrelated */')]))], // A44/A43 strip only their exact hunks
    ['unrelated sheep change', m => m.set('farm3d/sheep3d.js', Buffer.concat([m.get('farm3d/sheep3d.js'), Buffer.from('\n/* unrelated */')]))], // A45 whole-file pin
    ['unrelated chicken change', m => m.set('farm3d/chicken3d.js', Buffer.concat([m.get('farm3d/chicken3d.js'), Buffer.from('\n/* unrelated */')]))], // A45 whole-file pin
    ['unrelated index change', m => m.set('farm3d/index.html', Buffer.concat([m.get('farm3d/index.html'), Buffer.from('\n<!-- unrelated -->')]))],
    ['missing service worker', m => m.delete('farm3d/sw.js')],
    ['wrong cache version', m => m.set('farm3d/sw.js', Buffer.from(ui.normalizeA52Source('sw.js',m.get('farm3d/sw.js').toString()).replace('sa3d-v85', 'sa3d-v86')))], // A46: current cache is sa3d-v85
    ['unrelated unchanged asset', m => {const file = manifest.staticSource.find(e => !['farm3d/auth.js','farm3d/index.html','farm3d/sw.js'].includes(e.path)).path; m.set(file, Buffer.concat([m.get(file), Buffer.from('corrupt')]));}]
  ];
  controls.push(
    ['wrong A52 cache version',m=>m.set('farm3d/sw.js',Buffer.from(m.get('farm3d/sw.js').toString().replace('sa3d-v93','sa3d-v94')))],
    ...Object.keys(ui.scope.assets).flatMap(file=>[
      ['missing A52 '+file,m=>m.delete(file)],
      ['corrupt A52 '+file,m=>m.set(file,Buffer.from('corrupt'))]
    ])
  );
  for (const [, mutate] of controls) {const copy = new Map(source); mutate(copy); assert.throws(() => historicalAccounting(copy, manifest));}
  return controls.map(c => c[0]);
}

